//! Cargo-driven `srvsvc.dll` link, generated by tools/cargo_cell_gen.py
//! from the cmake link it replaces.
//! The body is srvsvc-rust; reactos-link builds the PE.

use reactos_link::{Linker, ModuleKind, MsvcrtexKind};
use std::env;

fn main() {
    let arch = env::var("CARGO_CFG_TARGET_ARCH").expect("CARGO_CFG_TARGET_ARCH");

    // The C left, and its part of cmake's C rule; reactos-link adds what every C
    // compile shares from reactos-link/cflags/c.<arch>.flags (Linker::c_compiled).
    let c_sources: &[&str] = &["@build/base/services/srvsvc/srvsvc_s.c"];
    let c_includes: &[&str] = &[
        "@build/base/services/srvsvc",
        "base/services/srvsvc",
        "@std",
        "vendor/opengl-headers/include",
        "vendor/libdxg/include",
        "sdk/include/reactos/idl",
    ];
    let c_flags: &[&str] = match arch.as_str() {
        "x86" => &[
            "-isystem",
            "{REPO}/sdk/lib/pseh/include",
            "-isystem",
            "{REPO}/sdk/lib/tdilib",
            "-isystem",
            "{REPO}/vendor/zlib/include",
            "-isystem",
            "{REPO}/vendor/libtiff/include",
            "-isystem",
            "{REPO}/vendor/symcrypt/inc",
            "-isystem",
            "{REPO}/vendor/symcrypt/lib",
            "-std=gnu99",
            "@core",
        ],
        "x86_64" => &[
            "-isystem",
            "{REPO}/sdk/lib/pseh/include",
            "-isystem",
            "{REPO}/sdk/lib/tdilib",
            "-isystem",
            "{REPO}/vendor/zlib/include",
            "-isystem",
            "{REPO}/vendor/libtiff/include",
            "-isystem",
            "{REPO}/vendor/symcrypt/inc",
            "-isystem",
            "{REPO}/vendor/symcrypt/lib",
            "-std=gnu99",
            "-U_X86_",
            "-UWIN32",
            "@core",
        ],
        "aarch64" => &[
            "-isystem",
            "{REPO}/sdk/lib/pseh/include",
            "-isystem",
            "{REPO}/sdk/lib/tdilib",
            "-isystem",
            "{REPO}/vendor/zlib/include",
            "-isystem",
            "{REPO}/vendor/libtiff/include",
            "-isystem",
            "{REPO}/vendor/symcrypt/inc",
            "-isystem",
            "{REPO}/vendor/symcrypt/lib",
            "-std=gnu99",
            "@core",
        ],
        _ => unreachable!(),
    };
    let c_defines: &[&str] = &[
        "UNICODE",
        "WINVER=0x502",
        "_CRT_DECLARE_NONSTDC_NAMES=1",
        "_CRT_NONSTDC_NO_DEPRECATE",
        "_DLL",
        "_UNICODE",
        "_WIN32_WINNT=0x502",
        "__USE_CRTIMP",
    ];

    // The module's part of cmake's windres command; reactos-link adds what every
    // module shares from reactos-link/cflags/rc.<arch>.flags (Linker::rc).
    let rc_includes: &[&str] = &[
        "@build/base/services/srvsvc",
        "base/services/srvsvc",
        "@std",
        "sdk/lib/pseh/include",
        "vendor/opengl-headers/include",
        "vendor/libdxg/include",
        "sdk/include/reactos/idl",
    ];
    let rc_flags: &[&str] = &[];
    let rc_defines: &[&str] = &["UNICODE", "WINVER=0x502", "_UNICODE", "_WIN32_WINNT=0x502"];

    let (target_json, entry, image_base) = match arch.as_str() {
        "x86" => ("i686-pc-windows-gnu", "_DllMainCRTStartup@12", Some(0x6e0e0000u64)),
        "x86_64" => ("x86_64-pc-windows-gnu", "DllMainCRTStartup", Some(0x7fe75000000u64)),
        "aarch64" => ("aarch64-pc-windows-gnullvm", "DllMainCRTStartup", Some(0x7fe75000000u64)),
        o => panic!("srvsvc-cargo: unsupported arch {o}"),
    };

    let late_libs: &[&str] = match arch.as_str() {
        "x86" => &["engine:wine", "engine:oldnames"],
        "x86_64" => &["engine:wine", "engine:oldnames"],
        "aarch64" => &["engine:wine", "engine:oldnames"],
        _ => unreachable!(),
    };

    Linker::new(target_json)
        .rust_staticlib("srvsvc-rust")
        .c_compiled("srvsvc_shims", c_sources, c_includes, c_flags, c_defines)
        .rc("base/services/srvsvc/srvsvc.rc", rc_includes, rc_flags, rc_defines)
        .spec2def("base/services/srvsvc/srvsvc.spec", "srvsvc.dll")
        .import_lib("dll/win32/advapi32/advapi32.spec", "advapi32.dll", "advapi32")
        .import_lib("dll/win32/rpcrt4/rpcrt4.spec", "rpcrt4.dll", "rpcrt4")
        .import_lib("dll/win32/msvcrt/msvcrt.spec", "msvcrt.dll", "msvcrt")
        .import_lib("dll/win32/kernel32/kernel32.spec", "kernel32.dll", "kernel32")
        .import_lib("dll/ntdll/def/ntdll.spec", "ntdll.dll", "ntdll")
        // ...and those cmake linked after the body, in the same order.
        .static_libs_after_body(late_libs)
        .msvcrtex_crt(MsvcrtexKind::Dll)
        .link(ModuleKind::Win32Dll {
            entry: entry.into(),
            image_base,
            subsystem: None,
        });
}
